	}
	shared := &Shared{
		Headers:      options.Options.ParseCustomHeaders(),
		Options:      options,
		hostBackoffs: backoffCache,
	}
	if options.Options.KnownFiles != "" {
		httpclient, _, err := BuildHttpClient(options.Dialer, options.Options, nil)
		if err != nil {
