			// they are sent to output without visiting
			if s.Options.Options.DisplayOutScope {
				s.Output(nr, nil, ErrOutOfScope)
			}
			continue
		}

		queue.Push(nr, s.priority(nr))

		if s.Options.Options.PathClimb {
